function buildWaffle(year) {
  const gt = year ? (D.yt[String(year)] || 1) : D.gt;
  const ordered = D.go.map(gid => D.tree.find(t => t.id === gid)).filter(Boolean);
  const groups = ordered.map(gr => {
    const val = year ? gr.ch.reduce((s, c) => s + g(D.ys, year + "|" + c.id), 0) : gr.v;
    const children = gr.ch.map(c => ({
      id: c.id, name: c.n, value: year ? g(D.ys, year + "|" + c.id) : c.v,
    })).filter(c => c.value > 0);
    return { id: gr.id, name: gr.n, color: gr.c, value: val, children };
  }).filter(g => g.value > 0);

  let cells = groups.map(g => ({ ...g, cells: Math.max(1, Math.round(g.value / gt * N)) }));
  const diff = cells.reduce((s, c) => s + c.cells, 0) - N;
  if (diff !== 0) cells[0].cells -= diff;

  const grid = [];
  for (const gr of cells) {
    for (let i = 0; i < gr.cells; i++) {
      grid.push({ groupId: gr.id, color: gr.color });
    }
  }
  return { grid, groups: cells, gt };
}

function WaffleChart({ year, isMobile }) {
  const COLS = isMobile ? 25 : 50;
  const { grid, groups, gt } = useMemo(() => buildWaffle(year), [year]);
  const [hoverGroup, setHoverGroup] = useState(null);
  const [openLegend, setOpenLegend] = useState(false);
  const hoveredData = hoverGroup != null ? groups.find(g => g.id === hoverGroup) : null;

  return (
    <div style={{ position: "relative" }}>
      <div style={{ display: "flex", flexWrap: "wrap", gap: isMobile ? "4px 8px" : "3px 12px", marginBottom: 10, fontSize: isMobile ? 10 : 11 }}>
        {groups.map(gr => (
          <div key={gr.id} style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 11, color: "#8899aa",
            opacity: hoverGroup === null || hoverGroup === gr.id ? 1 : 0.3, transition: "opacity .15s",
            cursor: "pointer" }}
            onMouseEnter={() => setHoverGroup(gr.id)} onMouseLeave={() => setHoverGroup(null)}>
            <div style={{ width: 10, height: 10, borderRadius: 2, background: gr.color, flexShrink: 0 }} />
            <span>{gr.name}</span>
            <span style={{ color: "#556", fontSize: 10 }}>{fmt(gr.value) + " (" + (gr.value / gt * 100).toFixed(1) + "%)"}</span>
          </div>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(" + COLS + ", 1fr)", gap: 2, background: "#0d1b2a", borderRadius: 8, padding: 4 }}
        onMouseLeave={() => setHoverGroup(null)}>
        {grid.map((cell, i) => {
          const isHover = hoverGroup === cell.groupId;
          const isDim = hoverGroup !== null && hoverGroup !== cell.groupId;
          return (
            <div key={i} style={{
              aspectRatio: "1", borderRadius: 3,
              background: cell.color, opacity: isDim ? 0.12 : 1,
              transition: "opacity .15s", cursor: "pointer",
            }} onMouseEnter={() => setHoverGroup(cell.groupId)} />
          );
        })}
      </div>

      {hoveredData && (
        <div style={{
          marginTop: 8, background: "rgba(10,22,40,.95)", borderRadius: 10, padding: "10px 14px",
          border: "2px solid " + hoveredData.color,
        }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: hoveredData.children.length > 1 ? 6 : 0 }}>
            <span style={{ fontWeight: 700, fontSize: 13, color: "#e8e8f0" }}>{hoveredData.name}</span>
            <span style={{ fontSize: 12, color: "#8899aa" }}>
              {fmt(hoveredData.value)} ({(hoveredData.value / gt * 100).toFixed(2)}%)
            </span>
          </div>
          {hoveredData.children.length > 1 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
              {hoveredData.children.sort((a, b) => b.value - a.value).map((ch, ci, arr) => {
                const chPct = ch.value / gt;
                const maxVal = arr[0].value;
                const barPct = maxVal > 0 ? (ch.value / maxVal) * 100 : 0;
                return (
                  <div key={ch.id} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 11 }}>
                    <div style={{ flex: 1, minWidth: 0, background: "rgba(255,255,255,.06)", borderRadius: 3, height: 16, position: "relative", overflow: "hidden" }}>
                      <div style={{ position: "absolute", inset: 0, width: Math.max(2, barPct) + "%", background: hoveredData.color, opacity: 0.4, borderRadius: 3 }} />
                      <span style={{ position: "relative", padding: "0 6px", lineHeight: "16px", color: "#ccd", fontSize: 10, whiteSpace: "nowrap" }}>
                        {ch.name}
                      </span>
                    </div>
                    <span style={{ color: "#8899aa", fontSize: 10, whiteSpace: "nowrap", width: 120, textAlign: "right", flexShrink: 0 }}>
                      {fmt(ch.value)} ({(chPct * 100).toFixed(2)}%)
                    </span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      <div style={{ marginTop: 12 }}>
        <button onClick={() => setOpenLegend(prev => !prev)} style={{
          background: "none", border: "1px solid #1e3a5f", borderRadius: 6, color: "#8899aa",
          padding: "5px 12px", fontSize: 11, cursor: "pointer", display: "flex", alignItems: "center", gap: 6,
        }}>
          <span style={{ transform: openLegend ? "rotate(90deg)" : "rotate(0deg)", transition: "transform .15s", display: "inline-block" }}>{"\u25B6"}</span>
          {"Co znamenaj\u00ed jednotliv\u00e9 kategorie?"}
        </button>
        {openLegend && (
          <div style={{ marginTop: 8, display: "flex", flexDirection: "column", gap: 8 }}>
            {D.tree.map(gr => {
              const desc = DESCRIPTIONS[gr.id];
              if (!desc) return null;
              return (
                <div key={gr.id} style={{ fontSize: 11, lineHeight: 1.6, padding: "10px 12px", background: "rgba(255,255,255,.02)", borderRadius: 6, borderLeft: "3px solid " + gr.c }}>
                  <div style={{ fontWeight: 700, color: "#e8e8f0", marginBottom: 4, fontSize: 12 }}>{gr.n}</div>
                  <div style={{ color: "#7888a0", marginBottom: desc.bullets ? 6 : 0 }}>{desc.text}</div>
                  {desc.bullets && (
                    <div style={{ display: "flex", flexDirection: "column", gap: 2, marginLeft: 8 }}>
                      {desc.bullets.map((b, i) => (
                        <div key={i} style={{ color: "#6b7b8d", display: "flex", gap: 6 }}>
                          <span style={{ color: gr.c, flexShrink: 0 }}>{"\u2022"}</span>
                          <span>{b}</span>
                        </div>
                      ))}
                    </div>
                  )}
                  {desc.note && (
                    <div style={{ color: "#8899aa", marginTop: 6, fontStyle: "italic", fontSize: 10, lineHeight: 1.5 }}>{desc.note}</div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}


function PragueMap({ year, isMobile }) {
  const [topN, setTopN] = useState(20);

  const items = useMemo(() => {
    return MAP.map(m => {
      const val = year ? (m.yr[String(year)] || 0) : m.v;
      return { ...m, val };
    }).filter(m => m.val > 0).sort((a, b) => b.val - a.val).slice(0, topN);
  }, [year, topN]);

  const maxVal = items.length > 0 ? items[0].val : 1;
  const minVal = items.length > 0 ? items[items.length - 1].val : 0;

  function getColor(val) {
    // Use rank-based coloring: distribute evenly across the gradient
    // regardless of value gaps. Find rank position.
    var idx = items.findIndex(function(m) { return m.val === val; });
    var t = items.length > 1 ? 1 - (idx / (items.length - 1)) : 1;
    // 3-stop: cream(#FFF3C4) -> burnt orange(#D55E00) -> dark crimson(#6B0000)
    var r, g2, b;
    if (t < 0.4) {
      var t2 = t / 0.4;
      r = Math.round(255 + (213 - 255) * t2);
      g2 = Math.round(243 + (94 - 243) * t2);
      b = Math.round(196 + (0 - 196) * t2);
    } else {
      var t2 = (t - 0.4) / 0.6;
      r = Math.round(213 + (107 - 213) * t2);
      g2 = Math.round(94 + (0 - 94) * t2);
      b = Math.round(0);
    }
    return "rgb(" + r + "," + g2 + "," + b + ")";
  }

  const mapHtml = useMemo(() => {
    var size = topN <= 20 ? 26 : topN <= 50 ? 22 : 18;
    var fsize = topN <= 20 ? 11 : topN <= 50 ? 9 : 7;
    const mj = JSON.stringify(items.map((m, i) => ({
      lat: m.lat, lng: m.lng, name: m.n,
      val: m.val, color: getColor(m.val), rank: i + 1, size: size, fsize: fsize,
    })));
    return [
      "<!DOCTYPE html><html><head><meta charset='utf-8'/>",
      "<link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css'/>",
      "<script src='https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js'><\/script>",
      "<style>html,body{margin:0;height:100%;overflow:hidden}#map{width:100%;height:100%}",
      ".lt{background:rgba(10,22,40,.95)!important;color:#e8e8f0!important;border:1px solid #1e3a5f!important;border-radius:8px!important;padding:6px 10px!important;font:12px system-ui!important;box-shadow:0 4px 12px rgba(0,0,0,.5)!important}",
      ".lt b{color:#fff}.leaflet-tooltip-top:before,.leaflet-tooltip-bottom:before,.leaflet-tooltip-left:before,.leaflet-tooltip-right:before{border:none!important}",
      ".ri{display:flex;align-items:center;justify-content:center;border-radius:50%;color:#fff;font-weight:700;text-shadow:0 1px 2px rgba(0,0,0,.6);border:2px solid rgba(255,255,255,.8);box-sizing:border-box}",
      "</style></head><body><div id='map'></div><script>",
      "var map=L.map('map',{center:[50.065,14.42],zoom:11,zoomControl:true});",
      "L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,crossOrigin:'anonymous',subdomains:'abc',attribution:'\\u00a9 OpenStreetMap'}).addTo(map);",
      "var ms=" + mj + ";",
      "ms.forEach(function(m){",
      "var icon=L.divIcon({className:'',html:'<div class=\"ri\" style=\"width:'+m.size+'px;height:'+m.size+'px;font-size:'+m.fsize+'px;background:'+m.color+'\">'+m.rank+'</div>',iconSize:[m.size,m.size],iconAnchor:[m.size/2,m.size/2]});",
      "L.marker([m.lat,m.lng],{icon:icon}).addTo(map)",
      ".bindTooltip('<b>'+m.rank+'. '+m.name+'</b><br/>'+m.val.toLocaleString('cs-CZ')+' p\\u0159estupk\\u016f',{className:'lt',direction:'top',offset:[0,-m.size/2-4]});",
      "});<\/script></body></html>"
    ].join("");
  }, [items, topN]);

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 10, flexWrap: "wrap" }}>
        <div style={{ display: "flex", gap: 4 }}>
          {[10, 20, 30, 50, 100].map(n => (
            <button key={n} onClick={() => setTopN(n)} style={{
              padding: "5px 10px", borderRadius: 6, border: "none", cursor: "pointer", fontSize: 11, fontWeight: 600,
              background: topN === n ? "#E69F00" : "#0d1b2a", color: topN === n ? "#fff" : "#8899aa",
            }}>{"Top " + n}</button>
          ))}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: "#8899aa", marginLeft: "auto" }}>
          <span>{"m\u00e9n\u011b"}</span>
          <div style={{ width: 80, height: 10, borderRadius: 5, background: "linear-gradient(to right, #FFF3C4, #D55E00, #6B0000)" }} />
          <span>{"v\u00edce"}</span>
        </div>
      </div>
      {items.length < topN && (
        <div style={{ fontSize: 10, color: "#5a6a7a", marginBottom: 6 }}>
          {"Zobrazeno " + items.length + " lokalit – pro toto období není více lokalit s ověřenou polohou"}
        </div>
      )}
      <iframe
        key={topN + "|" + String(year)}
        srcDoc={mapHtml}
        style={{ width: "100%", height: isMobile ? 300 : 450, border: "none", borderRadius: 8 }}
        sandbox="allow-scripts"
        title="Mapa"
      />
    </div>
  );
}


function TimeHist({ year }) {
  const data = useMemo(() => {
    if (year) return ML.map((m, i) => ({ label: m, count: g(D.ym, year + "|" + String(i + 1).padStart(2, "0")) }));
    return D.years.map(y => ({ label: String(y), count: D.yt[String(y)] || 0 }));
  }, [year]);
  const barColor = year ? "#E8686A" : "#C0392B";
  return (
    <ResponsiveContainer width="100%" height={200}>
      <BarChart data={data} margin={{ top: 8, right: 4, bottom: 0, left: 4 }}>
        <XAxis dataKey="label" tick={{ fontSize: 11, fill: "#8899aa" }} axisLine={false} tickLine={false} />
        <YAxis hide />
        <Tooltip formatter={v => [fmt(v), "p\u0159estupk\u016f"]}
          contentStyle={{ background: "#0d1b2a", border: "1px solid #1e3a5f", borderRadius: 8, fontSize: 12, color: "#e8e8f0" }} />
        <Bar dataKey="count" fill={barColor} radius={[3, 3, 0, 0]} label={{ position: "top", fontSize: 9, fill: "#8899aa", formatter: v => v > 0 ? (v >= 1000 ? Math.round(v/1000) + " tis." : v) : "" }} />
      </BarChart>
    </ResponsiveContainer>
  );
}

function AuthDonut({ year }) {
  const data = useMemo(() => {
    if (year) return [
      { name: "M\u011bstsk\u00e1 policie Praha", s: "MPP", value: g(D.yo, year + "|MPP") },
      { name: "Policie \u010cR", s: "P\u010cR", value: g(D.yo, year + "|P\u010cR") },
    ];
    const m = D.years.reduce((s, y) => s + g(D.yo, y + "|MPP"), 0);
    const p = D.years.reduce((s, y) => s + g(D.yo, y + "|P\u010cR"), 0);
    return [{ name: "M\u011bstsk\u00e1 policie Praha", s: "MPP", value: m }, { name: "Policie \u010cR", s: "P\u010cR", value: p }];
  }, [year]);
  const t = data[0].value + data[1].value;
  const C = ["#D55E00", "#F0E442"];
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>
      <ResponsiveContainer width={140} height={140}>
        <PieChart><Pie data={data} dataKey="value" cx="50%" cy="50%" outerRadius={60} innerRadius={36} strokeWidth={0}>
          {data.map((_, i) => <Cell key={i} fill={C[i]} />)}
        </Pie></PieChart>
      </ResponsiveContainer>
      <div style={{ fontSize: 12, width: "100%" }}>
        {data.map((d, i) => (
          <div key={d.s} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <div style={{ width: 12, height: 12, borderRadius: 3, background: C[i], flexShrink: 0 }} />
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 600, color: "#e8e8f0" }}>{d.name}</div>
              <div style={{ fontSize: 11, color: "#6b7b8d" }}>{fmt(d.value)} {" p\u0159estupk\u016f"}</div>
            </div>
            <div style={{ fontWeight: 700, fontSize: 16, color: C[i] }}>{t > 0 ? Math.round(d.value / t * 100) : 0}%</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function SubjectDonut({ year }) {
  const data = useMemo(() => {
    if (year) return [
      { name: "Fyzick\u00e1 osoba", s: "osoba", value: g(SUBJ, year + "|osoba") },
      { name: "Firma / provozovatel", s: "firma", value: g(SUBJ, year + "|firma") },
      { name: "Nep\u0159i\u0159azeno", s: "neprirazeno", value: g(SUBJ, year + "|neprirazeno") },
    ];
    const o = D.years.reduce((s, y) => s + g(SUBJ, y + "|osoba"), 0);
    const f = D.years.reduce((s, y) => s + g(SUBJ, y + "|firma"), 0);
    const n = D.years.reduce((s, y) => s + g(SUBJ, y + "|neprirazeno"), 0);
    return [
      { name: "Fyzick\u00e1 osoba", s: "osoba", value: o },
      { name: "Firma / provozovatel", s: "firma", value: f },
      { name: "Nep\u0159i\u0159azeno", s: "neprirazeno", value: n },
    ];
  }, [year]);
  const t = data.reduce((s, d) => s + d.value, 0);
  const C = ["#0072B2", "#CC79A7", "#BBBBBB"];
  return (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>
      <ResponsiveContainer width={140} height={140}>
        <PieChart><Pie data={data} dataKey="value" cx="50%" cy="50%" outerRadius={60} innerRadius={36} strokeWidth={0}>
          {data.map((_, i) => <Cell key={i} fill={C[i]} />)}
        </Pie></PieChart>
      </ResponsiveContainer>
      <div style={{ fontSize: 12, width: "100%" }}>
        {data.map((d, i) => (
          <div key={d.s} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <div style={{ width: 12, height: 12, borderRadius: 3, background: C[i], flexShrink: 0 }} />
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 600, color: "#e8e8f0" }}>{d.name}</div>
              <div style={{ fontSize: 11, color: "#6b7b8d" }}>{fmt(d.value)} {" p\u0159estupk\u016f"}</div>
            </div>
            <div style={{ fontWeight: 700, fontSize: 16, color: C[i] }}>{t > 0 ? Math.round(d.value / t * 100) : 0}%</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function DistChart({ year }) {
  const data = useMemo(() =>
    D.ds.map(d => ({
      name: d, count: year ? g(D.yd, year + "|" + d) : (D.dt[d] || 0),
    })).sort((a, b) => b.count - a.count)
  , [year]);
  return (
    <ResponsiveContainer width="100%" height={Math.max(420, data.length * 20)}>
      <BarChart data={data} layout="vertical" margin={{ top: 4, right: 55, bottom: 4, left: 4 }}>
        <XAxis type="number" hide />
        <YAxis type="category" dataKey="name" width={30}
          tick={{ fontSize: 11, fill: "#8899aa" }} axisLine={false} tickLine={false} interval={0} />
        <Tooltip formatter={v => [fmt(v), "p\u0159estupk\u016f"]} labelFormatter={l => "Praha " + l.replace("P", "")}
          contentStyle={{ background: "#0d1b2a", border: "1px solid #1e3a5f", borderRadius: 8, fontSize: 12, color: "#e8e8f0" }} />
        <Bar dataKey="count" fill="#009E73" radius={[0, 3, 3, 0]}
          label={{ position: "right", fontSize: 10, fill: "#6b7b8d", formatter: v => v > 0 ? fmt(v) : "" }} />
      </BarChart>
    </ResponsiveContainer>
  );
}

const Sec = ({ title, note, children }) => (
  <div style={{ background: "#0d1b2a", borderRadius: 12, padding: "16px 16px 12px", border: "1px solid #1e3a5f" }}>
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 10 }}>
      <h3 style={{ margin: 0, fontSize: 14, fontWeight: 600, color: "#e8e8f0" }}>{title}</h3>
      {note && <span style={{ fontSize: 11, color: "#5a6a7a" }}>{note}</span>}
    </div>
    {children}
  </div>
);

export default function Dashboard() {
  const [year, setYear] = useState(null);
  const winWidth = useWindowWidth();
  const isMobile = winWidth < 768;
  const total = year ? (D.yt[String(year)] || 0) : D.gt;
  const label = year ? String(year) : "2015\u20132023";

  return (
    <div style={{ fontFamily: "system-ui, -apple-system, sans-serif", color: "#e8e8f0", background: "#0a1628", minHeight: "100vh", padding: "24px 20px" }}>

      <div style={{ marginBottom: 20 }}>
        <h1 style={{ margin: 0, fontSize: 24, fontWeight: 700, letterSpacing: "-.02em" }}>{"Dopravn\u00ed p\u0159estupky v Praze"}</h1>
        <p style={{ margin: "4px 0 0", fontSize: 13, color: "#5a6a7a" }}>
          {"Data Magistr\u00e1tu hlavn\u00edho m\u011bsta Prahy \u00b7 " + label + " \u00b7 "}<strong style={{ color: "#E69F00" }}>{fmt(total)}</strong>{" p\u0159estupk\u016f celkem"}
        </p>
        <p style={{ margin: "8px 0 0", fontSize: 12, color: "#6b7b8d", lineHeight: 1.6, maxWidth: 700 }}>{"Interaktivn\u00ed p\u0159ehled dopravn\u00edch p\u0159estupk\u016f zaznamenan\u00fdch na \u00fazem\u00ed hlavn\u00edho m\u011bsta Prahy v letech 2015\u20132023. Dashboard vych\u00e1z\u00ed z otev\u0159en\u00fdch dat Magistr\u00e1tu hl. m. Prahy a umo\u017e\u0148uje filtrovat data podle jednotliv\u00fdch let, porovn\u00e1vat typy p\u0159estupk\u016f, spr\u00e1vn\u00ed obvody i nejfrekventovan\u011bj\u0161\u00ed lokality."}</p>
      </div>

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 20 }}>
        <button onClick={() => setYear(null)} style={{
          padding: "7px 14px", borderRadius: 8, border: "none", cursor: "pointer", fontSize: 12, fontWeight: 600,
          background: !year ? "#E69F00" : "#0d1b2a", color: !year ? "#fff" : "#8899aa",
        }}>Celkem</button>
        {D.years.map(y => (
          <button key={y} onClick={() => setYear(y)} style={{
            padding: "7px 12px", borderRadius: 8, border: "none", cursor: "pointer", fontSize: 12, fontWeight: 600,
            background: y === year ? "#E69F00" : "#0d1b2a", color: y === year ? "#fff" : "#8899aa",
          }}>{y}</button>
        ))}
      </div>

      <div style={{ marginBottom: 16 }}>
        <Sec title={"Typy p\u0159estupk\u016f"} note={isMobile ? label : "1 bu\u0148ka \u2248 0,2 % \u00b7 mo\u017en\u00fd rozsah 0,04\u20130,30 % kv\u016fli zaokrouhlen\u00ed \u00b7 " + label}>
          <WaffleChart year={year} isMobile={isMobile} />
        </Sec>
      </div>

      <div style={{ marginBottom: 16 }}>
        <Sec title={year ? "Po\u010det p\u0159estupk\u016f v jednotliv\u00fdch m\u011bs\u00edc\u00edch roku " + year : "Po\u010det p\u0159estupk\u016f podle roku"} note={year ? "leden\u2013prosinec" : "2015\u20132023"}>
          <TimeHist year={year} />
        </Sec>
      </div>

      <div style={{ marginBottom: 16 }}>
        <Sec title={"Lokality s nejvy\u0161\u0161\u00edm po\u010dtem zaznamenan\u00fdch p\u0159estupk\u016f"} note={label}>
          <PragueMap year={year} isMobile={isMobile} />
        </Sec>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 2fr", gap: 16 }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <Sec title="Oznamovatel" note={label}>
            <AuthDonut year={year} />
          </Sec>
          <Sec title={"Subjekt p\u0159estupku"} note={label}>
            <SubjectDonut year={year} />
          </Sec>
        </div>
        <Sec title={"Zaznamenan\u00e9 p\u0159estupky ve spr\u00e1vn\u00edch obvodech"} note={"Praha 1\u201322 \u00b7 " + label}>
          <DistChart year={year} />
        </Sec>
      </div>

      <div style={{ marginTop: 16 }}>
        <Sec title={"Metodologie zpracov\u00e1n\u00ed dat"} note="">
          <div style={{ fontSize: 11, color: "#7888a0", lineHeight: 1.7 }}>
            <p style={{ margin: "0 0 10px" }}>{"Data poch\u00e1z\u00ed z "}<a href="https://opendata.praha.eu/datasets" target="_blank" rel="noopener" style={{ color: "#56B4E9", textDecoration: "underline" }}>{"otev\u0159en\u00fdch dataset\u016f Magistr\u00e1tu hl. m. Prahy (MHMP)"}</a>{" a pokr\u00fdvaj\u00ed obdob\u00ed 2015\u20132023. P\u016fvodn\u00ed datasety obsahuj\u00ed jednotliv\u00e9 z\u00e1znamy o p\u0159estupc\u00edch s pr\u00e1vn\u00ed kvalifikac\u00ed (sloupec PRAVFOR), m\u00edstem skutku (MISTOSK), spr\u00e1vn\u00edm obvodem (PRAHA), oznamovatelem (OZNAM) a informac\u00ed o subjektu (OSOBA/FIRMA)."}</p>
            <p style={{ margin: "0 0 10px" }}><strong style={{ color: "#aab" }}>{"Kategorizace p\u0159estupk\u016f"}</strong>{" byla provedena na z\u00e1klad\u011b pr\u00e1vn\u00ed kvalifikace dle \u00a7125c\u2013f z\u00e1kona \u010d. 361/2000 Sb. Jednotliv\u00e9 body \u00a7125c/1f (rychlost, \u010derven\u00e1, telefon aj.) byly rozkl\u00ed\u010dov\u00e1ny z textov\u00e9ho pole PRAVFOR pomoc\u00ed regul\u00e1rn\u00edch v\u00fdraz\u016f. Sb\u011brn\u00e1 kategorie \u00a7125c/1k (\u201eParkov\u00e1n\u00ed a b\u011b\u017en\u00fd provoz\u201c) nebyla d\u00e1le d\u011blena, proto\u017ee data neobsahuj\u00ed popis skutku \u2013 pouze pr\u00e1vn\u00ed kvalifikaci. Odhad ~85 % parkov\u00e1n\u00ed v t\u00e9to kategorii vych\u00e1z\u00ed z textov\u00e9 anal\u00fdzy pole MISTOSK."}</p>
            <p style={{ margin: "0 0 10px" }}><strong style={{ color: "#aab" }}>{"Normalizace lokalit:"}</strong>{" Z\u00e1znamy v poli MISTOSK byly slou\u010deny podle n\u00e1zvu ulice/tunelu \u2013 varianty sm\u011bru, pruhu a \u010d\u00edsla popisn\u00e9ho byly agregov\u00e1ny pod jeden n\u00e1zev (nap\u0159. \u201eBrusnick\u00fd tunel sm\u011br Troja, pruh 1\u201c \u2192 \u201eBrusnick\u00fd tunel\u201c). GPS sou\u0159adnice byly p\u0159i\u0159azeny pomoc\u00ed Google Places API."}</p>
            <p style={{ margin: "0 0 10px" }}><strong style={{ color: "#aab" }}>{"Waffle chart"}</strong>{" pou\u017e\u00edv\u00e1 500 bun\u011bk (50\u00d710). Ka\u017ed\u00e1 kategorie m\u00e1 minim\u00e1ln\u011b 1 bu\u0148ku, co\u017e zp\u016fsobuje drobn\u00e9 zaokrouhlen\u00ed u nejmen\u0161\u00edch kategori\u00ed. Korekce je aplikov\u00e1na na nejv\u011bt\u0161\u00ed kategorii."}</p>
            <p style={{ margin: 0 }}><strong style={{ color: "#aab" }}>{"Vylou\u010den\u00e1 data:"}</strong>{" Z\u00e1znamy s hodnotou \u201emimo Prahu\u201c ve sloupci PRAHA byly vy\u0159azeny. Rok 2024 nebyl zahrnut \u2013 od 1. 7. 2024 bylo ukon\u010deno projedn\u00e1v\u00e1n\u00ed p\u0159estupk\u016f v prvn\u00edm stupni na MHMP a data jsou dostupn\u00e1 pouze do 30. 6. 2024."}</p>
          </div>
        </Sec>
      </div>

      <div style={{ textAlign: "center", fontSize: 10, color: "#3d4d5d", marginTop: 20, paddingBottom: 12 }}>
        {"Vytvo\u0159il Kry\u0161tof Henzl \u00b7 KISK, Masarykova univerzita \u00b7 S pomoc\u00ed "}<a href="https://claude.ai" target="_blank" rel="noopener" style={{ color: "#5a6a7a", textDecoration: "underline" }}>{"Claude (Anthropic)"}</a>
      </div>
    </div>
  );
}
